from pathlib import Path

import pandas as pd
import streamlit as st

st.title("7) Chapter Results (Reproducible Evidence)")

st.caption(
    "This page surfaces the publication assets generated by `python -m src.report` — "
    "the ablation study, model comparison with significance tests, bootstrap confidence "
    "intervals, calibration, SHAP explainability, external validation on NHANES, and the "
    "GeoAI prior-correction analysis. Every table and figure here is regenerated from code."
)

REPORTS = Path(__file__).resolve().parent.parent / "reports"

if not REPORTS.exists() or not (REPORTS / "metrics_summary.json").exists():
    st.warning(
        "No report assets found yet. Generate them first with:\n\n"
        "```bash\npython -m src.report\n```"
    )
    st.stop()


def show_csv(name: str, **kwargs):
    path = REPORTS / name
    if path.exists():
        st.dataframe(pd.read_csv(path), use_container_width=True, **kwargs)
    else:
        st.info(f"{name} not found — re-run `python -m src.report`.")


def show_pdf(name: str, caption: str):
    """PDFs don't render inline in Streamlit; offer a download + note the path."""
    path = REPORTS / name
    if path.exists():
        st.caption(f"📄 {caption} — `reports/{name}`")
        with open(path, "rb") as f:
            st.download_button(f"Download {name}", f, file_name=name, key=name)
    else:
        st.info(f"{name} not found.")


tab1, tab2, tab3, tab4, tab5 = st.tabs(
    ["Ablation & Models", "Calibration & ROC", "SHAP", "External Validation", "GeoAI"]
)

with tab1:
    st.subheader("Ablation study")
    st.caption(
        "Cross-validated ROC-AUC as each pipeline component is added. This shows that "
        "the design choices — zeros-as-missing handling, derived clinical features, "
        "ensembling — each contribute, rather than being incidental."
    )
    show_csv("ablation_table.csv")

    st.subheader("Model comparison with DeLong test")
    st.caption(
        "Repeated stratified 5-fold CV ROC-AUC per model. The DeLong p-value tests whether "
        "each model's AUC differs significantly from the best model — large p-values mean "
        "the simpler model is statistically indistinguishable, an honest and important finding."
    )
    show_csv("model_comparison.csv")

with tab2:
    st.subheader("Held-out metrics with 95% bootstrap CIs")
    st.caption("Point estimates with stratified bootstrap percentile confidence intervals (2000 resamples).")
    show_csv("bootstrap_cis.csv")
    col1, col2 = st.columns(2)
    with col1:
        show_pdf("calibration.pdf", "Reliability diagram (before/after Platt calibration)")
    with col2:
        show_pdf("roc_curves.pdf", "ROC curve with bootstrap confidence band")

with tab3:
    st.subheader("SHAP explainability")
    st.caption(
        "Global feature importance (mean absolute SHAP value) and a per-patient explanation. "
        "Glucose and BMI dominating matches clinical knowledge, validating the model for non-ML readers."
    )
    show_csv("shap_importance.csv")
    col1, col2 = st.columns(2)
    with col1:
        show_pdf("shap_summary.pdf", "SHAP global summary")
    with col2:
        show_pdf("shap_waterfall.pdf", "SHAP per-patient waterfall")

with tab4:
    st.subheader("External validation: Pima → NHANES")
    st.caption(
        "The model is trained on Pima and evaluated on an entirely separate cohort — "
        "NHANES 2017–2018 women aged 21+ (n≈1,181, 15.7% prevalence vs Pima's 34.9%). "
        "The internal-vs-external gap quantifies how well the model transports across populations."
    )
    show_csv("external_validation.csv")
    st.caption(
        "A drop from internal to external performance is expected and scientifically honest — "
        "it reflects real differences in measurement protocols, era, and population base rates."
    )

with tab5:
    st.subheader("GeoAI prior correction")
    st.caption(
        "The novel contribution: combining the personal model score with CDC PLACES "
        "county-level prevalence via odds-ratio prior correction across all 3,144 US counties."
    )
    col1, col2 = st.columns(2)
    with col1:
        show_pdf("geo_map.pdf", "County diabetes prevalence map")
    with col2:
        show_pdf("geo_prior_correction.pdf", "Prior-correction curves across county base rates")
    st.subheader("National prevalence measures (county medians)")
    show_csv("geo_measures_national.csv")
